import { AudioLinesIcon } from 'lucide-react';
import { useEffect, useRef } from 'react';
import type { Media } from './manifest.js';
import { cn } from '@/lib/utils';

/**
 * The reader's stage for a video or audio canvas (ADR 0035): the browser's own player, with its
 * accessible controls and caption menu, on the canvas's HLS stream. Browsers that play HLS
 * themselves (Safari, iOS, recent Chrome) get the stream as it is; elsewhere (Firefox) hls.js, its
 * light build of about 115 KB gzipped, feeds the element through Media Source Extensions, loaded
 * only when a work page plays something. Audio plays in a video
 * element too, so its caption tracks show; behind it sits an icon instead of a picture.
 */

/** HLS's media type, which browsers that play HLS themselves say they can play. */
export const HLS_TYPE = 'application/vnd.apple.mpegurl';

export default function MediaStage({
  media,
  poster,
  title,
  onFailed,
}: {
  readonly media: Media;
  /** A video's poster frame (an image URL). */
  readonly poster: string | undefined;
  /** Names the player for assistive technology. */
  readonly title: string;
  readonly onFailed: (failed: boolean) => void;
}) {
  const element = useRef<HTMLVideoElement>(null);
  // The latest handler, so a new function does not reload the stream.
  const failed = useRef(onFailed);
  useEffect(() => {
    failed.current = onFailed;
  });

  const { src } = media;
  useEffect(() => {
    const video = element.current;
    if (video === null) return undefined;
    failed.current(false);
    let cancelled = false;
    let player: { destroy: () => void } | undefined;
    if (video.canPlayType(HLS_TYPE) !== '') {
      video.src = src;
    } else {
      import('hls.js/light').then(
        ({ default: Hls }) => {
          if (cancelled) return;
          if (!Hls.isSupported()) {
            failed.current(true);
            return;
          }
          const hls = new Hls();
          hls.on(Hls.Events.ERROR, (_event, data) => {
            if (data.fatal) failed.current(true);
          });
          hls.loadSource(src);
          hls.attachMedia(video);
          player = hls;
        },
        () => {
          if (!cancelled) failed.current(true);
        },
      );
    }
    return () => {
      cancelled = true;
      player?.destroy();
      video.removeAttribute('src');
      video.load();
    };
  }, [src]);

  const sound = media.kind === 'sound';
  return (
    <div className="absolute inset-0 grid place-items-center">
      {sound && <AudioLinesIcon aria-hidden="true" className="size-16 text-viewer-foreground/30" />}
      <video
        ref={element}
        controls
        playsInline
        preload="metadata"
        // The stream and its caption files are on the API's origin (CORS `*`).
        crossOrigin="anonymous"
        poster={poster}
        aria-label={`${sound ? 'Audio' : 'Video'}: ${title}`}
        data-testid="media-player"
        onError={() => {
          // A stream the element cannot decode; not the reset when the stage unmounts.
          if (element.current?.src !== '') failed.current(true);
        }}
        className={cn('absolute inset-0 size-full', sound ? 'bg-transparent' : 'bg-black')}
      >
        {media.captions.map((track) => (
          <track
            key={track.src}
            kind="captions"
            src={track.src}
            srcLang={track.language}
            label={track.label}
          />
        ))}
      </video>
    </div>
  );
}
